  .site-footer { padding: 28px 20px 20px; }
  .hero-card { grid-template-columns: 1fr; }
  .hero-card .chart-cell { border-right: none; border-bottom: 1px solid var(--border-soft); }
  .heatmap { grid-template-columns: 80px repeat(12, 1fr); }
}

@media (max-width: 640px) {
  .grid-4 { grid-template-columns: 1fr 1fr; }
  .grid-3 { grid-template-columns: 1fr; }
  .grid-2 { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .topbar { padding: 10px 14px; font-size: 11px; gap: 12px; }
  .topnav { gap: 10px; font-size: 10px; }
